def evaluate(*, nearest_lookup=False):
    name='Prochitecture Streets / Evaluate curved profile depth ratio v1'
    if nearest_lookup:name+=' / Nearest interval lookup experiment v1'
    if name in bpy.data.node_groups:return bpy.data.node_groups[name]
    g=c.Graph(name);g.socket('Geometry','NodeSocketGeometry');g.socket('Index','NodeSocketInt');g.socket('t','NodeSocketFloat')
    g.socket('Input Valid','NodeSocketBool');g.socket('Ratio','NodeSocketFloat','OUTPUT');g.socket('Derivative','NodeSocketFloat','OUTPUT')
    g.socket('Valid','NodeSocketBool','OUTPUT')
    inp=g.node('NodeGroupInput');src=inp.outputs['Geometry'];count=c._count(g,src)
    owner=c.V(g,inp.outputs['Index']);raw=c.V(g,inp.outputs['t']);t=c.bounded(g,raw)
    read=lambda key,at,kind='FLOAT':c._read(g,src,'st_cg_'+key,at,kind)
    if nearest_lookup:
        # Prepared owner intervals span t=[0,1] in increasing order. Separating
        # owners by two units puts every own-owner knot closer than any foreign
        # knot. The nearest knot is one of the interval's two endpoints; move
        # back one index only when it lies above the query. Midpoint ties lead
        # to the same lower endpoint. This does not choose geometry by proximity.
        keys=g.setpos(src,g.xyz(c.named(g,'st_cg_t'),2.*c.named(g,'st_cg_owner','INT'),0.))
        nearest=g.node('GeometryNodeSampleNearest','Locate a bracket in the prepared depth table')
        nearest.domain='POINT';g.bind(keys,nearest.inputs['Geometry'])
        g.bind(g.xyz(t,2.*owner,0.),nearest.inputs['Sample Position'])
        at=c.V(g,nearest.outputs['Index'])
        lo=g.math('MAXIMUM',0.,at-g.math('GREATER_THAN',read('t',at),t))
    else:
        lo=0.;hi=g.math('MAXIMUM',0.,count-1.)
        # This unrolled field search handles every queried vertex independently.
        # MAX_SAMPLES=4096 bounds the required number of steps at twelve.
        for _ in range(12):
            mid=g.math('FLOOR',(lo+hi)*.5);mid_owner=read('owner',mid,'INT')
            # Compare owner and parameter separately, retaining parameter precision
            # at high owner indices and very short original knot intervals.
            left=g.math('LESS_THAN',mid_owner,owner)+g.math('COMPARE',mid_owner,owner)*(1.-g.math('GREATER_THAN',read('t',mid),t))
            lo=c.choose(g,left,mid,lo);hi=c.choose(g,left,hi,mid)
    end=g.math('MINIMUM',lo+1.,count-1.)
    final=(1.-g.math('COMPARE',read('owner',end,'INT'),owner))+g.math('LESS_THAN',read('t',end)-read('t',lo),1e-8)
    lo=g.math('MAXIMUM',0.,c.choose(g,final,lo-1.,lo));end=lo+1.
    a=read('t',lo);b=read('t',end);h=b-a;q=c.bounded(g,(t-a)/g.math('MAXIMUM',h,1e-8))
    y0=read('ratio',lo);y1=read('ratio',end);m0=read('ratio_slope',lo);m1=read('ratio_slope',end)
    A=2.*(y0-y1)+h*(m0+m1);B=3.*(y1-y0)-h*(2.*m0+m1);C=h*m0
    depth=((A*q+B)*q+C)*q+y0;derivative=((3.*A*q+2.*B)*q+C)/g.math('MAXIMUM',h,1e-8)
    depth=c.choose(g,g.math('LESS_THAN',q,1e-8),y0,c.choose(g,g.math('GREATER_THAN',q,1.-1e-8),y1,depth))
    derivative=c.choose(g,g.math('LESS_THAN',q,1e-8),m0,c.choose(g,g.math('GREATER_THAN',q,1.-1e-8),m1,derivative))
    valid=c.V(g,inp.outputs['Input Valid'])*g.math('GREATER_THAN',h,1e-8)
    for at in (lo,end):valid=valid*g.math('COMPARE',read('owner',at,'INT'),owner)
    valid=valid*g.math('GREATER_THAN',raw,-1e-7)*g.math('LESS_THAN',raw,1.0000001)
    valid=valid*g.math('GREATER_THAN',t,a-1e-7)*g.math('LESS_THAN',t,b+1e-7)
    out=g.node('NodeGroupOutput')
    for key,value in (('Ratio',depth),('Derivative',derivative),('Valid',valid)):g.bind(value,out.inputs[key])
    return g.g


def copy_with_nearest_lookup(root):
    """Opt-in disposable comparison; preserve all callers and interpolation math."""
    import hashlib
    from .curved_quad_fair_nodes import assign_group
    memo={};proof=[]
    def visit(tree):
        if tree in memo:return memo[tree]
        if tree.name=='Prochitecture Streets / Evaluate curved profile depth ratio v1':
            result=evaluate(nearest_lookup=True)
            proof.append(dict(original=tree.name,candidate=result.name,
                              original_nodes=len(tree.nodes),candidate_nodes=len(result.nodes)))
        else:
            children=[(node.name,visit(node.node_tree)) for node in tree.nodes
                      if node.type=='GROUP' and node.node_tree]
            changed=[(name,child) for name,child in children if child!=tree.nodes[name].node_tree]
            result=tree.copy() if changed else tree
            if changed:
                result.name='Qualification / Nearest depth dependency / '+hashlib.sha256(tree.name.encode()).hexdigest()[:16]
                for name,child in changed:assign_group(result.nodes[name],child)
        memo[tree]=result;return result
    result=visit(root)
    if not proof:raise ValueError('No prepared depth lookup found')
    return result,proof
